import re, zlib

data = open("Bankingly Technical Product Manager Ejercicio Teìcnico v2.pdf","rb").read()

# index objects
objs = {}
for m in re.finditer(rb'(\d+)\s+(\d+)\s+obj', data):
    num = int(m.group(1))
    start = m.end()
    end = data.find(b'endobj', start)
    objs[num] = data[start:end]

def get_stream(body):
    m = re.search(rb'stream\r?\n', body)
    if not m: return None
    s = m.end()
    e = body.find(b'endstream', s)
    raw = body[s:e]
    try: return zlib.decompress(raw)
    except Exception: return raw

# parse ToUnicode cmaps
def parse_cmap(txt):
    mapping = {}
    for blk in re.findall(rb'beginbfchar(.*?)endbfchar', txt, re.S):
        for a,b in re.findall(rb'<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>', blk):
            src = int(a,16)
            dst = ''.join(chr(int(b[i:i+4],16)) for i in range(0,len(b),4))
            mapping[src]=dst
    for blk in re.findall(rb'beginbfrange(.*?)endbfrange', txt, re.S):
        for a,b,c in re.findall(rb'<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>', blk):
            lo,hi,st = int(a,16),int(b,16),int(c,16)
            for i in range(lo,hi+1):
                mapping[i]=chr(st+i-lo)
    return mapping

font_cmap = {}   # font obj num -> mapping
for num, body in objs.items():
    m = re.search(rb'/ToUnicode\s+(\d+)\s+0\s+R', body)
    if m:
        tnum = int(m.group(1))
        st = get_stream(objs.get(tnum, b''))
        if st: font_cmap[num] = parse_cmap(st)

# page objects in order
pages = []
for num, body in objs.items():
    if re.search(rb'/Type\s*/Page[^s]', body):
        pages.append((num, body))
pages.sort()

def resources_fonts(body):
    # /Font <</F4 12 0 R ...>>
    m = re.search(rb'/Font\s*<<(.*?)>>', body, re.S)
    d = {}
    if m:
        for name, on in re.findall(rb'/(\w+)\s+(\d+)\s+0\s+R', m.group(1)):
            d[name.decode()] = int(on)
    return d

out = []
for num, body in pages:
    fonts = resources_fonts(body)
    cm = re.search(rb'/Contents\s+(\d+)\s+0\s+R', body)
    if not cm: continue
    content = get_stream(objs.get(int(cm.group(1)), b''))
    if not content: continue
    cur = None
    text = []
    for tok in re.finditer(rb'/(\w+)\s+[\d.]+\s+Tf|<([0-9A-Fa-f]+)>\s*Tj|(BT)|(ET)|([\d.-]+)\s+([\d.-]+)\s+Td', content):
        if tok.group(1):
            cur = font_cmap.get(fonts.get(tok.group(1).decode(), -1), {})
        elif tok.group(2):
            h = tok.group(2)
            codes = [int(h[i:i+2],16) for i in range(0,len(h),2)]
            for c in codes:
                text.append(cur.get(c, '') if cur else '')
        elif tok.group(3) == b'BT':
            text.append('\n')
    out.append(''.join(text))

print(("\n\n===== PAGE BREAK =====\n\n").join(out))
