input.content:
// Verifica que el resultado de "intentar ejecutar sin aprobar" QUEDE FIJO en el
// panel después de que el front refresque la bandeja. Corre el app.js real contra
// un DOM y un fetch simulados.
const fs = require("fs");

const elementos = {};
function nuevoElemento(id) {
  const clases = new Set();
  return {
    id, textContent: "", innerHTML: "", className: "", hidden: false, value: "",
    classList: {
      add: (c) => clases.add(c), remove: (c) => clases.delete(c),
      contains: (c) => clases.has(c),
      toggle: (c, on) => (on === undefined ? (clases.has(c) ? clases.delete(c) : clases.add(c))
                                           : (on ? clases.add(c) : clases.delete(c))),
      _todas: clases,
    },
    addEventListener: () => {},
  };
}
for (const id of ["consola", "consola-estado", "consola-mensaje", "consola-cuerpo",
                  "cliente", "analista", "contador-pendientes", "pendientes",
                  "resueltas", "evaluar", "cerrar-consola"]) {
  elementos[id] = nuevoElemento(id);
}
elementos["analista"].value = "ana.perez";

let manejadorDeClick = null;
globalThis.document = {
  getElementById: (id) => elementos[id],
  createElement: () => ({ set textContent(v) { this._t = v; }, get innerHTML() { return this._t; } }),
  addEventListener: (tipo, fn) => { if (tipo === "click") manejadorDeClick = fn; },
};

const PROPUESTA = {
  propuesta_id: "PROP-demo1234", cliente_id: "CLI-003", accion: "plan_de_pago",
  razonamiento: "razonamiento de prueba", tono_sugerido: "firme",
  consulto_datos: true, estado: "pendiente_de_aprobacion",
  fue_modificada_por_el_analista: false,
};
const CLIENTE = {
  cliente_id: "CLI-003", nombre: "Marisol Quiroga", tipo_de_producto: "tarjeta_de_credito",
  dias_de_atraso: 27, monto_adeudado: 258000, cuota_vencida: 95000,
  antiguedad_meses: 36, canal_preferido: "sms",
  historial_de_pagos: ["tardio", "a_tiempo", "no_pago"],
};

const llamadas = [];
globalThis.fetch = async (url, opciones) => {
  const metodo = (opciones && opciones.method) || "GET";
  const ruta = url.replace("http://localhost:8000", "");
  llamadas.push(`${metodo} ${ruta}`);
  const responder = (status, cuerpo) => ({ status, ok: status < 400, json: async () => cuerpo });

  if (ruta === "/clientes") return responder(200, [CLIENTE]);
  if (ruta === "/acciones") return responder(200, ["recordatorio", "plan_de_pago", "escalar"]);
  if (ruta === "/propuestas") return responder(200, [PROPUESTA]);
  if (ruta.endsWith("/ejecutar")) {
    return responder(403, {
      error: "ExcepcionAprobacionRequerida",
      detalle: "No se puede ejecutar la propuesta PROP-demo1234: su estado es " +
               "'pendiente_de_aprobacion' y se requiere aprobación humana.",
    });
  }
  return responder(200, {});
};

eval(fs.readFileSync("frontend/app.js", "utf8"));

const esperar = () => new Promise((r) => setTimeout(r, 30));

(async () => {
  await esperar(); // deja terminar iniciar()

  console.log("Llamadas de carga inicial:", llamadas.join(", "));
  console.log("Panel después de cargar  :", JSON.stringify(elementos["consola-cuerpo"].textContent));

  // Simula el click en "intentar ejecutar sin aprobar (demo)"
  const tarjeta = {
    dataset: { id: "PROP-demo1234" },
    querySelector: (sel) => (sel.includes("comentario") ? { value: "" } : { value: "plan_de_pago" }),
  };
  const boton = { dataset: { hacer: "intentar-ejecutar" }, disabled: false,
                  closest: (sel) => (sel === ".tarjeta" ? tarjeta : boton) };
  llamadas.length = 0;
  await manejadorDeClick({ target: { closest: () => boton } });
  await esperar();

  const encabezado = elementos["consola-estado"].textContent;
  const mensaje = elementos["consola-mensaje"].textContent;
  const cuerpo = elementos["consola-cuerpo"].textContent;
  const hayError = elementos["consola"].classList.contains("hay-error");

  console.log("\nLlamadas disparadas por el click:", llamadas.join(", "));
  console.log("\n--- Estado del panel DESPUÉS del refresco de la bandeja ---");
  console.log("encabezado:", encabezado);
  console.log("mensaje   :", mensaje);
  console.log("cuerpo    :", cuerpo.replace(/\s+/g, " ").slice(0, 110) + "…");
  console.log("clase hay-error:", hayError);

  const pruebas = [
    ["se hizo el refresco de la bandeja después de la acción", llamadas.includes("GET /propuestas")],
    ["el encabezado sigue mostrando el 403", encabezado.includes("HTTP 403")],
    ["el mensaje del gate sigue visible", mensaje.includes("se requiere aprobación humana")],
    ["el JSON del rechazo sigue en el cuerpo", cuerpo.includes("ExcepcionAprobacionRequerida")],
    ["el panel está marcado como error", hayError === true],
    ["el refresco NO escribió su propio 200 encima", !cuerpo.includes("plan_de_pago")],
  ];
  console.log();
  let fallas = 0;
  for (const [descripcion, ok] of pruebas) {
    console.log(`  ${ok ? "OK  " : "FALLA"}  ${descripcion}`);
    if (!ok) fallas++;
  }
  console.log(fallas === 0
    ? "\nEl 403 persiste después del refresco.\n"
    : `\n${fallas} comprobaciones fallaron.\n`);
  process.exit(fallas === 0 ? 0 : 1);
})();

